def main():
    entries=json.loads((ROOT/'out/cellar_catalog/inventory.json').read_text(encoding='utf-8'))['entries']
    bynum={e['number']:e for e in entries};covered=set()
    for s in S:
        covered.update(s['catalogue_numbers']); s['output']=f'{s["number"]:02d}_{s["id"]}_sheet.png'
        ref=ROOT/'out/cellar_catalog'/bynum[s['catalogue_numbers'][0]]['front'] if s['catalogue_numbers'] else ROOT/'out/cellar_catalog/00_contrechamp.png'
        if s['id']=='dark_herb':ref=ROOT/'art/concepts/cannabis/01_compacte.png'
        s['refs']=[str(ref),str(ROOT/'art/concepts/cannabis/01_compacte.png')]
        s['prompt']=BASE+s['brief']+f' Main title: "{s["number"]:02d} — {s["title"].upper()}".'
    expected=set(range(5,150));assert covered==expected,(expected-covered,covered-expected)
    (ART/'prompts.json').write_text(json.dumps(dict(tool='built-in image_gen',mode='generation from game references',wall_exclusions=[1,2,3,4],jobs=S),ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'{len(S)} sheets cover all {len(covered)} non-wall catalogue entries, plus expanded plan and new individual pots/lamps.')
if __name__=='__main__':main()
